    // Devuelve un saludo incluso cuando nombre sea null
    return ""
}

solution:
fun saludar(nombre: String?): String {
    val persona = nombre ?: "explorador"
    return "¡Hola, $persona!"
}

starterCode:
fun misionesCortas(minutos: List<Int>): List<Int> {
    // Devuelve las duraciones de 15 minutos o menos
    return emptyList()
}

solution:
fun misionesCortas(minutos: List<Int>): List<Int> {
    return minutos.filter { it <= 15 }
}

